"""Deterministic authoring assembly only. No gameplay, audio, approval or world command execution."""
from pathlib import Path
import hashlib
import json
import re

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
VERSION = "r3-author-candidate-1"
MATERIALS = []

def words(text):
    return len(re.findall(r"[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)*", text))

def material(mid, title, quest, kind, spot, root, paragraphs, details=(), access="public", long_audio=False, source_refs=None):
    pairs = [{"id": f"{mid}-p{i:02d}", "en": en.strip(), "zh": zh.strip()} for i, (en, zh) in enumerate(paragraphs, 1)]
    refs = source_refs or ["World_Story_Bible_v0.1.md:461-489", "English_Learning_System_v0.1.md:790-793", "Exploration_Level_Design_v0.1.md:421-454"]
    result = dict(id=mid, content_version=VERSION, translation_version=VERSION+"-zh", review_status="original_unreviewed", human_review="human_pending",
        title_zh=title, quest_ref=quest, kind=kind, location=dict(scene=spot.split(".")[0], spot=spot), source_root=root,
        access_class=access, target_band=6.5, calibration_status="human_pending_not_a_score", originality="new_original_bilingual_candidate",
        rights_status="original_text_candidate_human_pending", source_refs=refs, original_local_details=list(details), paragraphs=pairs,
        english_word_count=sum(words(p["en"]) for p in pairs))
    if kind == "listening_script":
        result.update(audio_asset="", audio_status="not_recorded", listening_experience_status="script_only_not_listening_accepted",
            planned_rate_wpm=[140,175], planned_audio_class="long_audio" if long_audio else "short_audio",
            estimated_duration_seconds_range=[round(result["english_word_count"]*60/175),round(result["english_word_count"]*60/140)],
            duration_status="word_count_estimate_only_not_measured_audio", actual_duration_seconds=None, transcript_access="available_without_score_or_reward_penalty",
            source_channel_available="written_transcript_only", voice_performer="human_pending", performance_and_voice_rights="human_pending")
    MATERIALS.append(result)
    return result

material("R3-Q301-R-LANDING", "货运站：到港与下一份委托", "Q-301", "short_notice", "R3-S01.guide", "r3-freight-arrival-notice", [
 ("Berth the Glimmer at the marked landing and let the freight clerk check the vessel-use record, the completed priory handover and your commission. Register the arrival here before entering the mine. This desk keeps the route back to the vessel available; it does not issue permission to operate underground machinery.", "请把微光号停在标记泊位，让货运员核对船只使用记录、已完成的修院交接与核查委托。进入矿井前在此登记到港。此台保留返回船只的通路；地下设备操作另需许可。"),
 ("The priory index names maintenance batch MC-2. Its destination is this district's workshop. Pera, the mine forewoman, can define a local inspection and rescue assignment. The documents already carried from the priory remain useful as references, but they do not contain the workshop's original checks or a completed finding about its signatory.", "修院索引指向检修批次MC-2，目的地是本区工坊。矿区领班佩拉可说明本地查验与救援工作范围。带来的修院文件可以作为索引，却没有工坊原始检查，也没有关于签章人的完整核查结论。")], ["MC-2 alias continues R2-Q204-R-BATCH; no new acceptance finding at landing"])

material("R3-Q301-R-COMMISSION", "佩拉的矿井工作委托", "Q-301", "mission_document", "R3-S02.pera", "r3-pera-local-work-assignment", [
 ("Pera's assignment covers the public mine route, the damaged drainage equipment, the three workers awaiting rescue and the checks needed to bring them back safely. The workers are identified on the work board as W1, W2 and W3. These are local rescue codes, not permission to publish their addresses or medical details. Record who has actually reached the receiving point.", "佩拉的委托包括矿井公共通路、受损排水设备、三名待救工人与安全返程检查。工作板以W1、W2、W3标记三人。这些是救援代号，公开住址或病情另需范围。应记录谁实际到了接收点。"),
 ("Start with a return route that remains usable if electrical power is lost. Check the fixed inspection ladder at the lift station. A working lift may save effort, but the ladder is the basic exit. Then clear the rail route, isolate the damaged pump feed and lower the local water level. No one should be sent through an unchecked wet electrical area just because a message says that help is waiting beyond it.", "先建立断电后仍可使用的返程路。到升降站检查固定检修梯。可用升降机能省力，梯道才是基本出口。随后清理轨道，隔离损坏的泵房供电并降低局部水位。不能因前方传来求援消息，就把人送进未经检查的潮湿电气区域。"),
 ("The town's emergency stock provides twelve meal portions, three first-aid packs and one declared shift of wage cover. Take and deliver these local supplies through the receiving desk; a draft request cannot create them. Their use is part of basic protection. Extra workshop packages will be allocated separately after the rescue. Personal equipment parts and the six-tower engineering cargo remain in their own accounts.", "矿镇应急库存提供十二份暖食、三包急救用品与一班工资保障凭据。应通过接收台实际领取和交付，写申请不能生成物资。这是基本保障；救援后另行分配额外工包。个人装备零件和六塔工程货仍在各自账内。"),
 ("Bring back the current instrument sheet as well as the workers. It can establish what was observed in the mine today. Keep the sampling stage, load setting and limitations in the report. The mine is operating at a high extraction setting and dangerous changes have been observed. The present rescue does not establish the full cause of those changes.", "除接回工人，也要带回当前仪表记录，说明今日矿内所见。报告保留取样阶段、负荷设置与限制。矿井目前以高强度抽取，现场出现危险变化；本次救援尚不能证明变化的完整原因。")], ["W1/W2/W3 local rescue group; 12 meal portions, 3 first-aid packs and one-shift local wage cover; not player reward or engineering supply"])

material("R3-Q301-R-SHIFT", "升降站班表与缺席记录", "Q-301", "short_notice", "R3-S04.shift_board", "r3-current-mine-shift-original", [
 ("Current shift board: W1, W2 and W3 were assigned to the cutting face. Their return boxes remain blank. A blank box means that this desk has not confirmed their return; it is not a death record. The signal clerk received a call from the cutting-face shelter after the lower route became blocked. Mark a return only when the receiving desk sees the person or verifies an actual escorted handover.", "本班工作板：W1、W2、W3分派至采掘面，返程栏仍空白。空白表示此台尚未确认返回，并非死亡记录。下层通路受阻后，信号员接到采掘面避护处呼叫。接收台实际见到本人或核对护送交接后，才能登记返回。"),
 ("Visitors must receive the mine safety briefing and the available basic kit before entering. The fixed ladder is listed separately from the powered lift. Tell the surface desk which route has been checked, and leave its access clear while any worker remains below.", "访客进入前应取得矿井安全说明与可领取的基础装备。固定梯道与电动升降机分列登记。请向地面台说明实际检查的通路；地下仍有人时保持出口畅通。")], ["Three-worker shift is a new local candidate, not an existing hidden completed-rescue state"])

material("R3-Q301-R-LADDER", "固定梯道：独立返程检查", "Q-301", "short_notice", "R3-S04.ladder", "r3-fixed-ladder-inspection-plate", [
 ("The fixed ladder links the lift station and the lower rail landing. Its support brackets and resting platform require a physical check. This inspection uses the installed ladder and the mine's basic safety kit; the optional portable clamp is not needed to reach the mine. Close the gate beside the moving lift while checking, and keep the ladder entry open to returning workers.", "固定梯道连接升降站和下层轨道平台，应现场检查支架及休息台。检查使用已装梯道和矿区基础安全装备，无需可选便携固定钳才能进入。检查时关闭活动升降机旁的门，给返程工人保留梯道入口。"),
 ("A later freight-lift repair can create a shorter return loop from the cutting face. It supplements this route. Reducing extraction power must not lock the ladder or remove its verified access. If the lift is unavailable, the checked ladder remains the safe route back.", "后来修复采掘面的货运升降支路，可形成更短回环，它补充此路。降低抽取供电不能锁梯或撤去已核查通路。升降机不可用时，已检查梯道继续提供安全返程。")])

material("R3-Q301-R-RAIL", "下层轨道清障作业告示", "Q-301", "short_notice", "R3-S05.route_notice", "r3-lower-rail-route-board", [
 ("Scrap and an active feeder obstruct the lower track. Check the marked work area from the safe platform before engaging the threat. The rail clearance is a separate work result from the later escort: removing the obstruction does not mean that the waiting workers have travelled through the route. Keep the fixed ladder and its landing accessible throughout both jobs.", "下层轨道有废料和活动送料装置阻挡。处置威胁前，从安全平台检查标记区域。清障与稍后的护送是不同工作结果；清除障碍尚不表示工人已经通过。两项工作期间均保留固定梯道和平台通路。"),
 ("The pump-room inspection passage branches from this track. The bypass label is readable from the maintenance stand, but handling its machinery needs the local assignment. A copy of the gauge sheet placed here retains the gauge's source reference. It does not become a second independent measurement just because it has been moved to this board.", "泵房检修通路从轨道分出。可从维护站位读取旁路标签，操作设备需要本地委托。此板上的仪表页副本保留仪表来源；放到另一块板上，不会成为第二次独立测量。")])

material("R3-Q301-R-PUMP", "泵房隔离、排水与复查", "Q-301", "mission_document", "R3-S06.pump_plate", "r3-damaged-pump-feed-plate", [
 ("The damaged feed supplies the pump-room drive. Identify that feed at the labelled isolation point and separate it from the wet work area. The isolation is local: it does not switch off the town's whole supply or the port generator. Deal with the threat at the pump entrance from the marked safe stand. A cleared entrance and an isolated feed are both required before the drainage controls may be handled.", "损坏线路给泵房驱动供电。应在标记隔离点确认这条线路，将它与潮湿作业区分离。该隔离只针对本地，不关闭整个矿镇供电或港口发电机。从安全站位处置泵房入口威胁；入口安全且线路隔离后才能操作排水控制。"),
 ("Drain the local pool, then inspect its level and the equipment again. The recorded check belongs to the actual configuration that was tested. Reconnecting the damaged feed or changing the pump arrangement requires a new inspection. Reading an older maintenance note can explain the equipment, but it cannot certify the present water level or a changed connection.", "排除局部积水，再复查水位和设备。检查记录对应实际受检配置。重新接入损坏线路或改变泵房安排，都须再次检查。旧维修便条能够说明设备，却不能认证当前水位或变更后的接线。"),
 ("When drainage and the present safety check are complete, the route to the cutting face can open. Retreat through the checked rail-and-ladder path if a new fault is found. A failed attempt leaves the people already received in the town safe and preserves any unrelated repair; it does not refill the pump room so that the same rescue can pay again.", "排水与当前安全复查完成后，可开放前往采掘面的通路。发现新故障时，沿已检查轨道和梯道退回。尝试失败不会危及已接到矿镇的人，也不撤去无关修复，更不会重新注满泵房来重复领取救援奖励。")])

material("R3-Q301-R-RESCUE", "采掘面：接应与货运回环", "Q-301", "short_notice", "R3-S07.crew_call", "r3-cutting-face-shelter-board", [
 ("W1, W2 and W3 are waiting at the cutting-face shelter. Locate each person and agree the return arrangement at the work stand. The shelter call describes where help is needed; it does not confirm a surface arrival. The lower-track escort must actually bring the group to the receiving route, and the town desk must receive them before the rescue report can be closed.", "W1、W2、W3在采掘面避护处等候。到工作站位逐一确认，并商定返程。求援呼叫说明哪里需要帮助，没有确认地面到达。下层轨道护送应实际把三人带到接收路线，矿镇台接收后，救援报告才能收束。"),
 ("The freight-lift branch can be repaired from this side and tested before use. Keep its repair and test records distinct. This creates an optional quicker loop to the lift station; the fixed inspection ladder remains available even if production is reduced. A repaired branch carries the same people, not a replacement group or a second rescue reward.", "货运升降支路可从此侧修复并在使用前测试。修复与测试各留记录；支路形成返回升降站的较短回环，减产后固定检修梯仍可使用。回环运送同一批人，不产生替代工人或第二份救援奖励。")])

material("R3-Q301-R-ENVIRONMENT", "现场观察：负荷与异常的范围", "Q-301", "mission_document", "R3-S07.environment", "r3-current-environment-original", [
 ("The local observation sheet records three successive work stages. At stages A, B and C, the extraction settings were 1, 2 and 3 load units. The associated disturbance readings were 4, 7 and 9 on the same local indicator. The indicator's numbers are relative readings for comparison, not a medical scale or a complete measurement of the mist sea. The instrument and its setting must be recorded with the sample.", "地方观察页记录三个连续工作阶段。A、B、C阶段抽取设置分别为1、2、3负荷单位，同一本地指示器的扰动读数为4、7、9。数值是用于比较的相对读数，并非医疗尺度或对整个雾海的完整测量。样本须附仪器与设置。"),
 ("Extraction and disturbance rose together in this short record. Pump operation, nearby machines and sampling conditions also need checking. The sheet provides a traceable question for the academic review: which factors can explain the pattern, and under what conditions could it be reproduced? It cannot by itself show that mining created the mist, that every district has the same response, or that a shutdown will clear the weather immediately.", "这份短记录里，抽取与扰动同时上升。泵房运作、附近机械和采样条件也需核查。资料为学城提出可追查问题：哪些因素能够解释此模式，怎样的条件下可以复现？仅凭它尚不能说明开采创造了雾海、每个地区反应相同，或停机会立即放晴。"),
 ("Inspect the present gauges and retain the original reference before packing a sample. A copied sheet carries the same observation. Keep any later repair record dated separately so that a corrected instrument is not described as having worked correctly throughout the earlier period.", "装样本前应查当前仪表，并保留原始索引。抄录页承载同一次观察。后来的维修记录另记阶段，修正后的仪表不能被写成此前始终正常。")], ["Local comparative stages A/B/C: extraction1/2/3, indicator4/7/9; descriptive candidate, no causal proof or measured player performance"])

material("R3-Q301-L-ROUTE", "信号员的返程更正脚本", "Q-301", "listening_script", "R3-S04.rescue_note", "r3-signal-clerk-firsthand", [
 ("Signal clerk: I first told the surface desk that the freight lift could carry the return group. Please change that note. The lift branch has not been tested from the cutting-face side, so it is not our present exit. The fixed inspection ladder beside the main lift is the route we can check now. It stays available when the power setting changes.", "信号员：我最初向地面台说，货运升降支路能运送返程人员。请更正这条便条。采掘面一侧尚未完成支路测试，所以它目前不是出口。现在可检查主升降机旁的固定梯道；供电设置变化后，这条路仍在。"),
 ("The last call used the codes W1, W2 and W3. I heard all three reply, but I was at this station, not beside them. I can confirm the call and the route instruction. The rescue team must confirm the people at the shelter, and the receiving desk must confirm their arrival. Do not mark those later steps from my message.", "上一呼叫用了W1、W2、W3代号，我听到三人回应，但我在此站，没有站在他们身旁。我能确认呼叫与通路指示。救援队须到避护处确认本人，接收台须确认到达；不能用我的消息填写后来步骤。"),
 ("Before sending anyone through, tell us which return route was inspected and whether the wet pump area has a current safety check. If a check fails, keep the group at the safe shelter and repair the local fault. There is no reason to erase the town's earlier receipts or ask people to return below after they have already been received.", "派人通过前，请说明哪条返程路已检查、潮湿泵房区域是否有当前安全记录。检查失败时，让人员留在安全避护处，修复本地故障。无需删除矿镇先前回执，也不能要求已接收的人重新下井。")])

material("R3-Q301-L-WORKER", "避护处呼叫脚本", "Q-301", "listening_script", "R3-S07.crew_call", "r3-shelter-worker-firsthand", [
 ("Worker W2: We are together in the marked shelter. W1 can walk with assistance, and W3 is keeping the return packs ready. The rail route was blocked when we came here. We have heard the pump fall quiet, but none of us has inspected its wet controls. Please check the water and the feed before asking us to move.", "工人W2：我们都在标记避护处。W1在帮助下能够行走，W3正整理返程用品。我们到这里时轨道受阻。听见泵停下来，但没人检查过潮湿控制器。请先查水位与线路，再安排我们移动。"),
 ("We need a route, a receiving person and the supplies at the far end. A faster lift would help if its present test is complete. If it is not, use the fixed ladder and the checked rest platform. Please tell the receiving desk that three people are expected; the expectation must stay open until it sees us arrive.", "我们需要通路、接收人和另一端的物资。如果货运升降支路当前测试完成，它能帮忙省力；否则请使用固定梯道和受检休息台。请通知接收台预计有三人，实际见到到达前保留待接收状态。"),
 ("We can describe the changes we noticed during work. We cannot say what the instrument measured while we were away from it, or why the accepted repair sheet differs from the check sheet. Bring those sheets to the workshop. Our rescue should not depend on choosing a position in that argument.", "我们能说明工作时注意到的变化，却不能说明离开后仪器测到什么，也不知道为何合格验收页和检查页不同。请把两份记录带到工坊；救援不该取决于我们在争议中选择哪种立场。")], ["Worker assistance and shelter dialogue are original local details, no actual audio or human voice rights"])

material("R3-Q302-R-RAW", "MC-2原始仪表与旁路检查页", "Q-302", "mission_document", "R3-S07.raw_gauge", "r3-mc2-instrument-original", [
 ("Original check sheet, batch MC-2, inspection stage I. Six listed checks belong to this local batch. Four are marked complete. Checks MC-2-05 and MC-2-06, covering the safety bypass, are marked incomplete. The sheet records the test configuration and the observing instrument. A later official acceptance must be compared with this version; a recently repaired bypass cannot change what this earlier sheet recorded.", "原始检查页，批次MC-2，检查阶段I。本地批次列六项检查，四项完成。涉及安全旁路的MC-2-05与MC-2-06标为未完成。页面记录测试配置及观察仪表，应与后来的正式验收版本比较；近日修好的旁路不能改变早页记录。"),
 ("The original instrument can be read from the inspected maintenance stand after the branch hazard is controlled. Record its plate, version and present reading. A workshop transcription of these entries preserves their source. It may confirm the chain of copying, but it is still this instrument record rather than an independent second observation.", "支路危险处置后，可从受检维护站位读取原仪表。请记标牌、版本与当前读数。工坊抄录保留来源，可以核对传递链，但承载的仍是此仪表记录，并非第二次独立观察。"),
 ("The two incomplete checks describe a safety function that had not been restored at stage I. Keep that scope in a finding. This sheet alone does not name every decision maker, explain the later supply quota, or resolve the wider cause of dangerous changes. Those questions require additional records and technical review.", "两项未完成检查说明，阶段I的安全功能尚未恢复。核查结论保留这个范围。仅此页尚未识别全部决策者，无法解释后来供给配额，也未解决危险变化的广泛原因；那些问题需要更多记录与技术核验。")], ["Six MC2 checks and MC2-05/06 aliases are original local candidate data"], access="controlled_review")

material("R3-Q302-R-COPY", "工坊留存副本与修订页", "Q-302", "mission_document", "R3-S03.workshop_copy", "r3-mc2-instrument-original", [
 ("Workshop retained copy, source MC-2 instrument sheet, stage I. This transcription retains the original plate reference and the entries for checks 05 and 06: incomplete. The copy was filed before the final acceptance form. Inspect its copying reference and compare the actual fields. Two sheets repeating this entry preserve a source in two places; they do not count as two observers of the test.", "工坊留存副本，来源为阶段I的MC-2仪表页。抄录保留原标牌索引，05、06项仍为未完成。副本先于最终验收表入档，应检查抄录索引并比较实际字段。两张纸复述同项记录，表示一来源保存在两处，没有增加两名测试观察者。"),
 ("A separate present repair line may be added when a repair is actually carried out. It must name the new work stage, parts and reviewer. Preserve the retained copy as the earlier version. Do not cross out the incomplete entries, replace the old signature, or call an intended repair a completed check.", "实际维修后，可以另加当前维修条目，注明新阶段、零件与复核人。保留副本仍代表早版本；不能涂掉未完成条目、替换旧签名，或把拟做维修写成完成检查。"),
 ("The local inspection assignment permits this batch comparison. It does not permit the release of unrelated household details or the alteration of priory records. If the original instrument remains temporarily inaccessible, the retained copy can guide preparation, while the final finding keeps the missing inspection explicit.", "本地查验委托允许这项批次比较，没有许可发布无关住户细节或改写修院记录。原仪表暂时无法到达时，可用副本准备工作；最终结论仍明确缺少哪项现场查验。")], ["Copy shares raw source_root; a present repair is a separate dated version"], access="controlled_review")

material("R3-Q302-R-SIGNED", "正式验收v3：奥伦签章", "Q-302", "short_notice", "R3-S03.signed_record", "r3-mc2-formal-acceptance-v3", [
 ("Formal acceptance, MC-2 version 3: all six listed checks are marked accepted, including the safety-bypass entries 05 and 06. The authorised signatory field bears Oren's signature. The workshop custodian retains the signature reference and the version used for delivery. Compare these fields with the stage-I check sheet and its retained copy.", "正式验收，MC-2版本3：六项列为合格，包括安全旁路05、06项。授权签章栏为奥伦签名，工坊保管人留有签名索引与交付版本。请与阶段I检查页及留存副本比较这些字段。"),
 ("Acceptance and physical completion are different record fields. Establish which work the signature accepted, which condition the instrument documented and whether a later repair belongs to a later stage. The public finding can identify the signed unsafe acceptance while preserving questions about wider instructions and the later network decisions.", "合格验收与物理完成是不同字段。应核对签名验收什么工作、仪表记载什么状态，以及后来的维修是否属于后阶段。公共核查可说明不安全验收及其签章，同时保留关于广泛指示和后来网络决定的问题。")], ["Formal v3 and checks05/06 are original local aliases of locked unsafe-acceptance fact"], access="controlled_review")

material("R3-Q302-R-BATCHES", "四批记录的统计比较", "Q-302", "mission_document", "R3-S03.comparison", "r3-workshop-four-batch-comparison", [
 ("The comparison covers four local batches, MC-1 to MC-4, with six listed checks in each batch: twenty-four checks altogether. The on-site incomplete counts are 0, 2, 1 and 0 respectively. The official accepted counts are 6, 6, 5 and 6. These columns describe different fields for the same group of checks, not two groups of workers or all equipment in the district.", "比较包括MC-1至MC-4四个本地批次，每批六项，共二十四项。现场未完成数依次为0、2、1、0，正式合格数依次为6、6、5、6。两列衡量同组检查的不同字段，不是两组工人，也不是本区全部设备。"),
 ("MC-2 has two incomplete on-site checks although its acceptance form marks all six accepted. MC-3 leaves one official acceptance open alongside an incomplete check. To explain the MC-2 discrepancy, inspect its particular fields, source versions and signature. The aggregate table helps locate a disagreement; it cannot identify the cause of every accident from a total alone.", "MC-2有两项现场未完成，验收表却把六项全部列为合格。MC-3的一项正式验收与未完成检查均仍待处理。解释MC-2差异须查具体字段、来源版本和签章。汇总表帮助定位冲突，不能仅凭总数识别每次事故的原因。"),
 ("The displayed comparison becomes available after a lawful inspection of the original instrument, retained copy and formal form. A written summary should state its local scope, compare the main patterns and identify the records needed to examine a discrepancy. Preserve the counts as recorded; explain an uncertainty rather than filling it with an assumed event.", "依法检查原始仪表、留存副本与正式表后，才提供此比较。书面摘要应注明本地范围、比较主要模式，并说明检查差异需要哪些记录。保留所记数值；解释未知，不用假定事件填空。")], ["Original visual data: four batches ×6, incomplete0/2/1/0, accepted6/6/5/6; calibration pending"], access="controlled_review")

material("R3-Q302-R-STATEMENT", "奥伦：责任说明与可核验安排", "Q-302", "mission_document", "R3-S03.oren", "r3-oren-own-statement", [
 ("Oren: I signed the MC-2 acceptance. The check sheet beside it still said that the safety bypass was incomplete. I should have refused to sign it as complete. I can describe the pressure during that handover, and I will answer questions about my own actions. My account should be compared with the instrument, workshop copy and formal version rather than used in their place.", "奥伦：MC-2验收是我签的，旁边的检查页仍写安全旁路未完成。我本该拒绝签为完成。我可以说明交接时受到的压力，也会回答关于本人行动的问题。请把陈述与仪表、工坊副本和正式版本比较，而不要拿它代替那些记录。"),
 ("You may request a public statement within an agreed scope, a supervised period of specific repair followed by a statement, or a regional review. None of those arrangements deletes the signed record. If you ask me to repair something, identify the equipment, supplies, person checking it and end of the assignment. An apology cannot fill those fields.", "可以要求在约定范围公开证言，安排有监督的具体限期维修后补交说明，或交由地区核查。这些安排均不删除签章记录。若让我修理，应列设备、物资、复核人和工作结束边界；一句道歉填不出这些条件。"),
 ("An invitation to join your travelling crew can be discussed after this batch finding is complete. Accepting, declining or delaying that invitation leaves the documents available under the inspection assignment. I cannot work a local duty post and take a travelling combat position at the same time.", "这项批次核查完成后，可以另谈加入出行队伍的邀请。接受、拒绝或暂缓都保留委托范围内的文件。本人不能同时占用本地当班岗位与出行战斗位置。")], ["New dialogue elaborates locked admission; no recruitment-required evidence"])

# Complete long reading and long discussion scripts remain unreviewed author candidates.
material("R3-Q302-R-HISTORY", "长读：修好之后，记录还说明什么", "Q-302", "extended_reading", "R3-S03.comparison", "r3-workshop-records-essay-original", [
 ("A repaired warning device changes what people can safely do tomorrow. It may allow a worker to hear a signal from another room, or let a supervisor repeat a check without standing beside the machine. That practical value should be recorded clearly. The repair also leaves a question about yesterday. If the earlier form said that the device had passed a check which was never completed, the new result cannot tell us that the old form was accurate. A useful account has room for both the present improvement and the earlier disagreement.", "修好的警报装置会改变明日能够安全做的事。工人也许能在另一个房间听到信号，主管也许能在机器旁之外重复检查，这些实用价值应记清。维修同时留下关于昨日的问题：早表若写着通过一项从未完成的检查，新结果无法证明早表准确。可用记录应容纳当前改善与早先差异。"),
 ("This distinction matters when an inspection has several stages. One person observes the instrument, another makes a workshop copy, and a signatory accepts the delivered work. Those actions are connected, but they have different responsibilities. The observer records a condition under stated settings. The copy preserves that observation and its source. The acceptance records a decision about whether the work meets a requirement. Placing the three pages together makes it possible to ask where their claims agree and where a decision went beyond the evidence available at that stage.", "检查有多个阶段时，这一区分格外有用。一人观察仪表，另一人抄成工坊副本，签章人验收交付。行动相连，职责各异：观察者在注明设置下记状态；副本保存观察及来源；验收页记录工作是否符合要求的判断。并列三页，就能比较主张在哪些地方一致、何处决定超出了当时证据。"),
 ("Copies are often necessary. An instrument sheet may remain underground while a surface team needs to arrange supplies. A carefully referenced transcription lets that team work without carrying away the only original. Yet two copies of a single observation do not make the observation independent. Counting documents can conceal this weakness. A stronger comparison identifies the original, follows the copying path and then seeks a genuinely different record, such as the acceptance decision. The purpose is to understand what each source contributes, rather than to collect the largest pile of paper.", "副本常有必要：仪表页可能留在井下，地面人员却要安排供给。有清楚索引的抄录让团队开展工作，也避免拿走唯一原稿。不过，同一观察的两份副本没有使观察变为独立。数文件容易掩盖这一点。更稳妥的比较会识别原稿、追溯抄录路径，再查真正不同的记录，例如验收决定；目的在于理解各来源的作用。"),
 ("A signature also has a scope. It can identify the person who accepted a particular version, without showing that this person invented every instruction attached to the wider system. Equally, uncertainty about wider instructions does not make the signature disappear. A signatory can explain a deadline, a shortage or pressure from a supervisor, and that explanation may help a review. It should remain separate from the check of what was signed. Otherwise an account of difficult circumstances can quietly replace the evidence of an action which still needs to be addressed.", "签名也有范围：它可识别某一版本的验收者，未必说明此人设计了整个系统的所有指示。对于广泛指示的未知，也不会让签名消失。签章人可以说明期限、短缺或主管压力，帮助核查；这些说明应与签了什么分开。否则，关于困难处境的叙述可能悄悄替换仍需处理的行动证据。"),
 ("Workers have practical reasons to want a repair accepted quickly. A closed route may stop wages, delay a meal delivery or leave a household waiting for someone to return. Treating every request for continued production as greed misses those conditions. Accepting an unsafe system without a limit can expose the same people to another danger. A responsible repair plan therefore needs more than a declaration of good intention: it needs a usable exit, a real supply arrangement, people assigned to the work and a point at which its conditions will be checked again.", "工人有实际理由希望迅速完成验收。通路关闭可能影响工资、拖延供餐，也让住户等不到家人回来。把每项继续生产请求都解释为贪婪，会漏掉这些条件；无限制接受不安全系统，又会把同一批人置于危险。负责的维修方案需要可用出口、实际供给、明确人员和再次核查边界，而非只有善意宣言。"),
 ("Some of the next steps can be agreed before a wider inquiry ends. A local team can isolate a damaged connection, replace a part and ask someone other than the repairer to repeat the test. It can record that result without writing that all previous decisions were justified. A resident may appreciate the new signal and still have questions about the earlier acceptance. Requiring forgiveness as the price of a safety receipt would give that receipt a purpose it cannot serve. The condition tested, the observer and the remaining disagreement can all stay visible.", "广泛核查结束前，仍可商定下一些工作。本地队能隔离损坏接线、换件，并请维修者之外的人重复测试；记录结果时无需宣称此前决定都合理。住民可能感谢新的信号，仍质疑早先验收。若把原谅当安全回执的代价，就赋予回执无法承担的作用。受检状态、观察人和余下分歧可以同时保留。"),
 ("The records themselves need suitable access. A public finding can describe the batch, incomplete function and signed decision while unnecessary household details remain protected. A controlled reviewer may need the full technical fields and a route to the original. These arrangements should specify a recipient, purpose and version. They should also explain how a challenge can reach the reviewer. A promise that evidence exists is of little help if the promised source cannot be inspected or if an old permission has been stretched to cover a new use.", "记录需要合适访问范围。公共结论可以说明批次、未完成功能与签章决定，同时保护无关住户信息。受控复核人也许需要完整技术字段及查原稿的通路。这些安排应注明接收方、用途、版本，并说明如何提出质疑。若承诺来源无法查阅，或把旧许可扩成新用途，仅声称有证据并没有多大帮助。"),
 ("The mine comparison has a useful, limited end. It can establish that an unrestored safety bypass was accepted as completed work and connect that decision to a verified signature. It can also preserve the observed changes in extraction and disturbance for further testing. The academic review will need to examine settings, instruments and other possible explanations before making a broader technical claim. Carrying forward those open questions does not weaken the local finding. It gives the next team a clear account of what is supported, what has changed and what still needs evidence.", "矿区比较具有有限而有用的终点：它能核实未修好的安全旁路曾按完成验收，并把决定与已核验签章联系起来，也能保留抽取和扰动变化供进一步试验。学城须查设置、仪表与其他解释，再形成广泛技术主张。带着未解决问题继续调查，不会削弱地方结论，而会让下一队知道哪些有依据、哪些改变了、哪些仍缺证据。")], ["Original complete essay about record scope; not a new causal or later-chapter finding"])

material("R3-Q302-L-CHECK", "长听脚本：三份记录，三个问题", "Q-302", "listening_script", "R3-S03.comparison", "r3-workshop-comparison-discussion", [
 ("Pera: Before we decide what to send, I want the three records kept on the table. The instrument sheet describes the local check at stage I. The workshop copy follows that sheet, and the final acceptance is version three. People have been calling them three separate witnesses. That wording worries me. We have three documents, but one repeats another. Please explain what each can establish, and keep the current rescue apart from the earlier acceptance. The workers need to come home whether or not they want to discuss who signed a form.", "佩拉：决定送什么之前，我希望三份记录都留在台上。仪表页记阶段I检查，工坊副本承接该页，最终验收是第三版。有人把它们叫三名独立证人，这个说法让我担心。我们有三份文件，其中一份复述另一份。请说明各自能核实什么，把当前救援与早验收分开；工人无论是否愿意谈签章，都需要回家。"),
 ("Workshop custodian: The source reference on the copy leads back to the instrument sheet, MC-2.instrument.I@1. Its retained-copy identity is MC-2.retained.I@1. Both record checks zero five and zero six as incomplete. I checked that the transcription preserves those fields. That is a copying check, rather than a new observation of the machine. The final form, MC-2.acceptance@3, marks all six accepted. We should compare the exact fields and the work they describe, rather than treating a large stamp as more reliable than a small handwritten line.", "工坊保管人：副本来源指向MC-2.instrument.I@1，留存副本身份为MC-2.retained.I@1。两页均把05、06项列为未完成。我核对抄录保留了这些字段；这是抄录检查，并非对机器的新观察。最终表MC-2.acceptance@3把六项全部列为合格。应比较具体字段与对应工作，不能因大印章就认为比小手写条目可靠。"),
 ("Oren: I signed that final form. I had seen the unfinished entries, and I should have refused to accept the bypass as complete. There was pressure to release the equipment for the next shift. I can give an account of that pressure and the instructions I received, but I will keep it separate from my signature. I cannot make the earlier check complete by repairing the device today. If I undertake a repair now, its parts, test and reviewer must be entered as new work, while the signed form remains available.", "奥伦：最终表是我签的。我看到了未完成条目，本该拒绝把旁路验收为完成。当时受到放行设备给下一班的压力。我会说明压力与收到的指示，但要把这些与本人签名分开。今天修理不能完成早先检查。若现在承接维修，应把零件、测试和复核人记成新工作，同时保留旧签章表。"),
 ("Pera: I am willing to discuss that new work, but it must have an end we can inspect. Naming a repairer is not enough. Tell us which device is included, where its supplies come from and who can repeat the check. The household auxiliary alarm may be a suitable separate job. It is not the flooded pump room again. I also want the town's wage cover and meals recorded before extra packages are allocated. A person asked to bear the cost of a shutdown needs to know what is actually waiting at the receiving desk.", "佩拉：我愿意谈新工作，但它要有可检查的终点。仅列维修人不足，还应说明设备、物资来源与复查者。住区辅助警报器可以成为另一项工作，不是再次把泵房注满。额外分配前，也要记清矿镇工资保障与暖食。被要求承担停产代价的人，需要知道接收台究竟准备了什么。"),
 ("Custodian: The four-batch table can help us present the records, as long as we state its denominator. Each batch has six listed checks. The incomplete counts are zero, two, one and zero; the official accepted counts are six, six, five and six. Those are two different measures of the same twenty-four entries. The table makes MC-2 worth examining closely. It does not tell us the history of every machine, or prove that every observed disturbance came from the same cause. The original fields are still needed for the particular finding.", "保管人：四批表可以帮助呈现记录，前提是保留分母。每批六项，未完成数为零、二、一、零；正式合格数为六、六、五、六。两列衡量同一组二十四项的不同方面。表格提示细查MC-2，但没有叙述全部机器历史，也未证明所有扰动来自同一原因。具体结论仍需要原字段。"),
 ("Oren: If a public statement is requested, agree its fields and purpose with me. I can speak about my own action, including the signature, without guessing the intentions of people whose later decisions I did not see. A supervised repair followed by a statement is another arrangement, and a regional review is also possible. Please do not call a delayed statement a missing signature. The verified record remains. Joining a travelling crew is a further decision, and I can decline that invitation without taking the workshop file away from the inquiry.", "奥伦：若要求公共证言，请与我商定字段和用途。我能说明本人行动，包括签名，不能猜测后来未亲见决定的动机。也可以先做监督维修再补证言，或交地区核查。请勿把延后陈述说成签名不存在。已核验记录仍在；加入出行队是另一决定，我拒绝邀请也不会拿走工坊档案。"),
 ("Pera: My response to a repair can stay narrower than forgiveness. I can accept a tested alarm and still object to the way the old equipment was delivered. Another qualified person can repeat the test if the arrangement is agreed; the repairer cannot sign both the work and its independent review. We should give residents a result they can use and a way to report a new fault. No one has to write that everyone is satisfied before the safety work can be recorded. The disagreement deserves its own line.", "佩拉：我对维修的回应可以小于原谅。我能接受受检警报器，仍反对早先交付方式。安排获准后，可请另一合格人员重复测试；维修者不能同时签工作及独立复核。住民应得到可用结果和报告新故障的途径。安全工作登记无需先写所有人满意；分歧自有一栏。"),
 ("Custodian: Then the outgoing package should retain the stage-I instrument reference, its copying chain and the acceptance version. Add the current environment readings with their settings and sampling conditions. List what this local comparison establishes and what the academic team still needs to test. The receiving desk must acknowledge the actual package and sample; an address written at the top of a draft does not deliver them. We can carry the inquiry forward while leaving the later cause, wider instructions and current whereabouts of people outside this inspection explicitly open.", "保管人：送出包应保留阶段I仪表索引、抄录链和验收版本，再附当前环境读数、设置与取样条件。列明地方比较核实什么、学城仍需试验什么。接收台应确认实际资料与样本；在草稿顶写地址并未完成交付。调查能够继续，同时把后来原因、广泛指示与此查验之外人物现址保留为未知。")], ["Original eight-turn long discussion; three document business versions are visible; no real recording"], long_audio=True)

material("R3-Q301-R-BASIC", "基本救援库存与住区接收", "Q-301", "short_notice", "R3-S02.shelter", "r3-town-basic-protection-inventory", [
 ("The emergency receiving desk holds twelve meal portions, three first-aid packs and a voucher covering one declared wage shift. The mine briefing also makes a basic safety kit available: a helmet, lamp and assistance line for the inspected route. These belong to the local rescue assignment. Collect them at the desk and record their actual delivery; listing them in a request is not a receipt.", "应急接收台有十二份暖食、三包急救物资和保障一班工资的凭据。矿井说明另提供基本安全包：用于受检通路的头盔、照明和辅助绳。这些属地方救援委托；应到台领取、登记实际交付，申请清单不是回执。"),
 ("W1, W2 and W3 must be received after the real escort. Confirm the checked exit, receiving person and basic provisions. Extra work packages remain unallocated until this protection is in place. A later change in production may alter the extra arrangement, but it does not withdraw meals or send received workers below again.", "W1、W2、W3须在实际护送后接收。核对受检出口、接收人和基本物资。保障成立前，额外工包仍待分配；后来生产变更可以改变额外安排，但不能撤回暖食或让已接收工人再次下井。")], ["New local physical basic kit and emergency stock; no unique optional equipment requirement or player-stat bonus"])

material("R3-Q303-R-DEMAND", "基本负荷与额外需求板", "Q-303", "mission_document", "R3-S08.demand_board", "r3-dispatch-load-and-needs-board", [
 ("The local supply has a capacity of ten load units. Basic protection uses seven: two for drainage, two for ventilation, two for the warm room and one for signals. Keep those services available after the rescue. Extraction uses a separate setting of zero to three additional units. At three, the combined load reaches ten. The unit is a local planning measure, not an engineering component or a currency.", "地方供电容量为十负荷单位。基本保障用七：排水二、通风二、暖房二、信号一。救援后继续保留这些服务。抽取设置另为零至三附加单位；设为三时总负荷达十。单位用于地方规划，并非工程组件或货币。"),
 ("The six extra work packages can support shelter improvement, retrofit work or limited production support. At least two must go to shelter and at least one to retrofit. Production support may receive zero to three, and the three allocations must total six. The packages are counted separately from the twelve basic meals, first aid and wage voucher already delivered.", "六个额外工包可用于安置改善、改造或有限生产支持。安置至少二包，改造至少一包；生产支持可获零至三包，三项合计为六。工包与已交付的十二份基本暖食、急救物资和工资凭据分别计数。"),
 ("A delivery plan should identify the recipients and retain an actual stores-to-work receipt. Compare the opportunity costs: a package used now for production support is unavailable for the same stage's shelter improvement. A package set aside for retrofit will help only when the work and its responsible people are arranged. State what is being postponed as well as what is being provided.", "交付计划应注明接收方，并保留库存到工作的实际回执。请比较机会代价：此阶段用于生产支持的工包，不能同时改善安置。改造工包也须配合真实工作与负责人员才有作用。说明提供什么，也说明推迟什么。")], ["Original public constraints: capacity10/essential7, six extra kits, shelter>=2 retrofit>=1 production0..3 and sum6"])

material("R3-Q303-R-STOCK", "调度所：六工包实际归属", "Q-303", "mission_document", "R3-S08.stores", "r3-extra-local-work-package-stock", [
 ("Six extra packages, LOCAL-R3-01 to LOCAL-R3-06, are held in the dispatch store for this assignment. They contain local work supplies rather than personal upgrade parts. Each package must have one recorded owner or receiving work group at a time. Reserving a package for an agreed arrangement does not deliver it, and the same package cannot be listed against both shelter and production.", "六个额外工包LOCAL-R3-01至06由调度库为本委托保管，内为地方作业用品，不是个人改件零件。每包同一时刻只有一项归属或接收工作组。为约定安排预留尚未交付，同包不能同时列于安置和生产。"),
 ("Before confirmation, an allocation can be revised while the packages remain in the store. After actual delivery, record their current destination and any work already done. Revising a draft cannot pull installed material back out or print a second copy of a spent package. An arrangement that needs a package no longer available must be changed or supplied through a lawful new source.", "确认前，工包仍在库内时可以修改分配。实际交付后，要保留当前位置及已做工作。改草稿不能拔回安装材料，或复制已使用工包。新安排若需要已不存在的工包，须修改方案或通过合法新来源补足。"),
 ("The six-tower ledger has different cargo and later work orders. Local packages do not satisfy TWR-R3's isolator, backup source, provision or enhanced-control requirements. The auxiliary alarm repair also uses its own workshop parts. Keep all three accounts distinct when describing a feasible plan.", "六塔工程账有不同货物和后续工单。地方工包不能满足TWR-R3隔离器、备用源、供给或增强控制需求；辅助警报器又使用自己的工坊零件。可行方案应保留这三项独立账目。")], ["Six local unique package IDs and separate ownership; no new global reward economy"])

material("R3-Q303-R-CHOICES", "降载与一班过渡的公开约束", "Q-303", "mission_document", "R3-S08.policy", "r3-public-local-policy-limits", [
 ("Choose a load policy explicitly. Under early_reduce, set extraction to zero and retain the seven basic service units. More of the extra packages can then go directly to shelter and retrofit, though the present extraction output is lost. A feasible example allocates four packages to shelter, two to retrofit and none to production support. Other allocations within the public limits can be proposed.", "请明确选择负荷政策。early_reduce把抽取设为零，保留七单位基本服务；更多工包可立即用于安置与改造，代价是失去当前抽取产出。可行例为安置四、改造二、生产支持零；也可提出满足公开约束的其他分配。"),
 ("Under time_limited_transition, extraction may use one to three units, with the total never above ten. The window lasts one declared work shift. Two different local duty people must actually accept the operating and safety-watch posts. A feasible allocation is shelter two, retrofit one and production support three. It preserves limited output for transfer work, with less immediate improvement elsewhere. An open-ended continuation is outside the safe arrangement.", "time_limited_transition允许抽取一至三单位，总量不超过十，窗口仅一班明确工作。两名不同本地人员须实际承接操作和安全观察岗。安置二、改造一、生产支持三是一例：保留有限产出用于转移工作，同时减少其他方面的即时改善。无限期延续超出安全安排。"),
 ("At the dispatch duty stand, close_transition_shift performs the handover and sets extraction back to zero before the next shift. This is a world-work boundary, not a countdown while someone reads or writes. A load change invalidates the previous configuration test. Recheck the actual new setting. The tower handover needs a current bounded policy, real duty records and the relevant test; saving the policy text alone does none of those jobs.", "在调度值守站位，close_transition_shift实际交班，并在下一班前把抽取降回零。这是世界工作边界，不是阅读或写作时的倒计时。负荷变更使旧配置测试失效，应复查新设置。塔站交接需要当前受限政策、真实值守和对应测试；仅保存政策文字没有完成这些工作。")], ["early_reduce/time_limited_transition and one world-work shift; two distinct duty occupants; close_transition_shift actual handover invalidates old test"])

material("R3-Q303-R-ESSAY", "长读：矿镇需要怎样的过渡", "Q-303", "extended_reading", "R3-S02.provision_notice", "r3-pera-public-resource-essay", [
 ("The request to reduce extraction reached the town while the rescue desk was still preparing its receiving space. It sounded simple from a distance: stop the dangerous work and send everyone home. At the desk, several questions followed. Which room would be warm? How would water be kept out of the lower route? Who would cover the next wage shift, and where would the supplies for a different kind of work come from? Those questions did not make safety less urgent. They described the work required to make a safer decision possible.", "减抽取请求来到矿镇时，救援台仍在准备接收空间。从远处听，事情似乎简单：停危险工作，让大家回家。台前却接着出现问题：哪间屋能保暖？如何防止下层通路进水？谁保障下一班工资？另一类工作的物资从哪里来？这些问题没有降低安全紧迫性，它们说明让更安全决定成为可能的实际工作。"),
 ("The first distinction is between basic protection and the extra choices which remain afterwards. A person needing first aid should not compete with a workshop project for the same promised packet. The checked exit, meals, warm room and agreed wage cover belong to the basic arrangement. Once those are actually provided, the extra packages can be discussed. Keeping separate records helps people see whether a proposal improves something additional or merely renames a service that should already be present. It also makes a shortage harder to hide behind a broad description of support.", "第一项区分是基本保障与后来额外选择。需要急救的人不该与工坊项目争夺同一份已承诺用品。受检出口、暖食、暖房和约定工资保障属于基本安排，实际落实后才谈额外工包。独立记录让人看清提案是新增改善，还是换名描述本就应提供的服务，也更难用宽泛支持措辞掩盖短缺。"),
 ("Early reduction has a clear attraction. It removes the extra extraction load immediately and leaves more work supplies available for shelter and retrofit. Residents can see improvements begin, while the mine team checks what a lower setting changes. The cost is also real. Output expected from the current work period will be absent, and a transfer which depended on that output needs another arrangement. A responsible argument for early reduction should explain that substitution. It should not imply that stopping one process automatically provides transport, different employment or every part needed for a future tower conversion.", "尽早降载有明显吸引力：立即撤去额外抽取负荷，留下更多作业物资用于安置和改造。住民可看到改善开始，矿队同时检查低设置的变化。代价也真实：本工作期预期产出缺失，依赖该产出的转移需要替代安排。支持早降载的论证应说明如何替代，不能暗示停一道工序就自动提供运输、新工作和后续塔改造所有部件。"),
 ("A limited transition may preserve enough output to support a particular transfer. It can be useful when the equipment and people must move in an order that cannot be changed at once. Its conditions are more demanding than the words 'for a short time' suggest. The load must have a cap, the window must have an end and two real people must accept the operating and safety-watch posts. There must also be a usable response when a check fails. Without those details, the temporary arrangement can quietly become ordinary production under a more reassuring name.", "有限过渡可能保留完成特定转移所需的产出，适用于设备与人员必须按难以立即改变的顺序移动时。其条件比“短时间”四个字更严格：负荷有上限，窗口有终点，两名真实人员承接操作与安全观察岗，检查失败时也有可用处置。缺少这些细节，临时安排可能悄悄以更令人放心的名称变为日常生产。"),
 ("Allocation makes the trade-off visible. The district has six extra packages for this work stage, and a package cannot be delivered twice. Giving one to production support means it is unavailable for a shelter improvement during the same stage. Holding one for retrofit may improve a later arrangement, but only if someone can perform that work. Different groups may value those outcomes differently. A useful discussion compares what is delayed, who carries that delay and which conditions can be checked. It need not describe one eligible allocation as the only compassionate choice.", "分配让取舍可见。本阶段有六个额外工包，同包不能交付两次。交给生产支持，就无法在同阶段改善安置；留作改造也须有人实际执行才会改善后来安排。不同群体可能重视不同结果。可用讨论应比较推迟什么、谁承担推迟、哪些条件可检查，不必把某一种合格分配写成唯一有同情心的选择。"),
 ("The account must include wages without confusing them with a traveller's reward. Local wage protection belongs to the town's emergency arrangement. The coins or equipment parts earned for a completed commission have another owner and purpose. Asking a resident to wait for food until an investigator writes a better paragraph would confuse these responsibilities. Equally, an investigator cannot solve the shortage by listing imaginary stock. A receipt from the actual store and receiving group provides a firmer basis for discussion than either a polished promise or a large number written without a source.", "记录须包含工资，并与出行者奖励分清。本地工资保障属于矿镇应急安排，完成委托取得的刻币和装备零件有另一归属与用途。让住民等调查者写好段落才领食物，会混淆职责；调查者也不能靠列虚构库存解决短缺。实际库存与接收组的回执，比漂亮承诺或没有来源的大数字更能支持讨论。"),
 ("A decision can be revised, but revision has physical limits. Before delivery, the team can change the distribution while the packages remain available. After a connection has been installed or supplies used, a new plan must acknowledge that state. Writing a different destination does not return the old package to the store. The same principle applies to duty. A person who leaves for a travelling assignment needs a local replacement before taking a new post. Clear revision rules let people change their minds without pretending that completed work and existing commitments vanish with the previous draft.", "决定可以修改，修改也有物理边界。交付前，物资仍在时可改分配；接线已安装或用品已消耗后，新计划应承认现状。另写目的地不能让旧工包回库。值守同理：某人离开参加出行工作前，需要本地接替。清楚的修订规则允许改变主意，也无需假装完成工作和已有承诺随旧稿消失。"),
 ("The end of a transition should be an action people can recognise. The duty team hands over, extraction falls to the agreed lower setting and the changed configuration is checked again. There is no benefit in making that boundary a penalty for reading slowly. It belongs to the actual work schedule. Recording its result gives the next shift something more useful than a statement that the plan once sounded reasonable. The safety route stays open, and the basic services continue while the team decides whether further work can be authorised.", "过渡终点应成为人们能辨认的行动：值守组交班，抽取降至约定低设置，再检查变更配置。把边界变成慢读惩罚毫无帮助，它属于实际工作安排。记录结果，才能让下一班获得比“计划曾听来合理”更有用的信息。安全返程继续开放，基本服务继续运行，再决定是否可授权后续工作。"),
 ("These local choices do not settle the whole network's future. They create a safer present stage and supply evidence for the next inquiry. The academic team will still need to examine how load, extraction and observed disturbance relate under controlled conditions. Residents should be able to inspect the local costs without being asked to endorse a technical conclusion that has not been tested. A good arrangement leaves them with protection, an accountable receiving chain and an honest explanation of the work which remains. Its value comes from those results, not from the elegance of the argument used to propose it.", "地方选择尚未决定整个网络未来，而是建立更安全的当前阶段，并为下一调查提供证据。学城仍需在受控条件下核查负荷、抽取和扰动的关系。住民应能查地方代价，无需被要求认可尚未试验的技术结论。好的安排留下保障、可追责接收链，以及对未完成工作的诚实说明；价值来自结果，而非提案论证的漂亮程度。")], ["Original complete resource essay; wage cover is task supply not player marks; eligible stances do not select an ending"])

material("R3-Q303-L-MEETING", "长听脚本：调度桌上的两条路", "Q-303", "listening_script", "R3-S08.allocation", "r3-local-resource-meeting-original", [
 ("Pera: The receiving desk has confirmed the three workers and the basic provisions. We can now discuss the extra six packages. I want the discussion to start from what is in the store, rather than what we hope a later shipment may bring. The basic services use seven of the ten load units: drainage two, ventilation two, warm room two and signals one. Keep that line separate. Reducing extraction must leave those services and the inspected ladder available. We are choosing an extra arrangement, not reopening the question of whether rescued people receive first aid.", "佩拉：接收台已确认三名工人与基本物资，现在可以谈六个额外工包。请从实际库存开始，不从希望后来有的船货开始。基本服务占十单位中的七：排水二、通风二、暖房二、信号一。这一行独立保留。减抽取须保留这些服务和受检梯道；现在选择额外安排，不重新争论被救者能否领急救用品。"),
 ("Stores clerk: Every extra package has one local identifier. If four go to shelter and two to retrofit, all six are allocated and none remain for production support. That is a feasible early-reduction distribution. Two to shelter, one to retrofit and three to production also meets the allocation limits. It supports a limited transition with less immediate improvement in the other two uses. We can consider a different distribution within the same limits. What I cannot sign is a list of seven packages, or a list which sends the same package to two groups.", "库管员：每个额外工包有独立地方编号。安置四、改造二就用完六包，不剩生产支持，这是一种可行早降载分配。安置二、改造一、生产三也符合限制，可支持有限过渡，但其他两项即时改善较少。还可考虑同限额内的别种分配。我不能签七包清单，也不能把同一包送给两个组。"),
 ("Local operator: I can take the operating post for the declared transition shift, if another person accepts the safety-watch post. Those must be different occupants. Extraction can be set from one to three units while the basic seven remain. Three reaches the total capacity of ten; four would exceed it. My acceptance covers this shift, not a permanent permission to keep the machine at the highest setting. At handover we will close the window and lower extraction to zero before the next shift begins. The changed setting will require a new test.", "地方操作员：若另一人承接安全观察岗，我可承担这班明确过渡的操作岗，两岗须是不同人员。保留基本七单位时，抽取可以为一至三；三恰达总容量十，四就超量。我的承诺只覆盖本班，没有永久允许机器保持最高设置。交班时我们结束窗口，在下一班前把抽取降到零，并重新测试变更设置。"),
 ("Resident representative: The warmer shelter matters now, but so does the transfer which some households are waiting for. I would like the proposal to say which work is postponed under each distribution. If we choose the transition, when will the materials used for production support become unavailable for shelter improvement? If we reduce immediately, who will replace the expected output in the transfer plan? We should be able to disagree about those costs without losing the meals and wage cover already agreed. Please record the conditions, rather than writing that every resident shares one preference.", "住民代表：更暖的安置处现在重要，一些住户等待的转移也重要。我希望提案说明各分配推迟什么工作。选择过渡后，生产支持物资何时不再可用于安置？立刻减产时，转移计划的预期产出由什么替代？讨论这些代价不应失去已约定暖食和工资保障。请记条件，不写所有住民同一偏好。"),
 ("Pera: The delivery is the point at which the packages move from the store to the named work. Before that, a draft may be revised while the stock remains. Afterwards we must retain the real destination and whatever has already been used. A new paragraph cannot return installed material. The town's emergency wage voucher is also separate from the travelling commission's reward. I will not ask someone to fund the agreed basic protection from personal upgrade parts, and I will not describe the six-tower cargo as if it were already in this store.", "佩拉：交付使工包从库内转到具名工作。此前，库存仍在时可以改草稿；此后须保留真实去向及已用材料，新段落不能返还已安装物资。矿镇应急工资凭据也与出行委托奖励分开。我不会要求用个人改件零件填已约定基本保障，也不会把六塔货物说成已在本库。"),
 ("Safety watcher: I can accept the separate watch post and record the checks for the current configuration. If a connection or load setting changes, the earlier pass does not remain current. A fault needs a safe response, and the fixed return route must stay usable. The written handover should identify me and the operator, the setting tested and the window's end. It can acknowledge uncertainty about the wider disturbance pattern. Our work establishes a local bounded operation; it does not certify the cause of every mine hazard or authorise a future central-network policy.", "安全观察员：我可承接独立观察岗，记录当前配置检查。接线或负荷变化后，旧通过不能继续算当前有效。故障须有安全处置，固定返程保持可用。书面交接应列我与操作员、受检设置和窗口终点，也可说明广泛扰动模式仍不确定。我们建立本地有界运行，尚未认证所有危险原因，也未授权未来中央政策。"),
 ("Stores clerk: I have one further correction to the draft. It says the auxiliary alarm parts will come out of these six packages. They will not. The workshop offers a separate repair pack for that invited job, and the engineering ledger holds different tower components. Please keep the three accounts named. A repair can be useful without being a tower upgrade. If the proposed recipients change before delivery, show me the new distribution and check the stock again. If the packages have already moved, start from their actual current ownership instead of the old reservation.", "库管员：草稿还需更正一处：它说辅助警报器零件来自这六包，实际并非如此。工坊为获邀工作另备维修包，工程账又有不同塔部件，请分列三账。维修可以有用，无需把它叫成塔升级。交付前接收方改变时，请带新分配复查库存；已经转移后，从当前归属开始，不从旧预留开始。"),
 ("Pera: Then state the chosen policy and the allocation you want confirmed. Explain the costs you accept and the limits you will keep. We will check the real stock, receiving group, load and duty arrangement before the work is submitted. Saving the draft lets us keep your reasoning; the separate confirmation and delivery create the result. When the transition is closed, record the handover and retest the lower load. The next team should inherit a usable route and an honest record, not a reassuring phrase whose conditions no longer match the equipment.", "佩拉：请注明要确认的政策与分配，说明接受的代价及保留限制。提交前会查真实库存、接收组、负荷和值守。保存稿件保留推理，另行确认和交付才形成结果。过渡结束时，登记交班并复查低负荷。下一队应接到可用通路和诚实记录，而非条件已与设备不符的安心措辞。")], ["Original eight-turn long meeting; anonymous duty roles not two copies of one actor; no real audio"], long_audio=True)

material("R3-Q304-R-SEQUENCE", "深井塔：开采机的停机次序", "Q-304", "mission_document", "R3-S09.machine", "r3-deepwell-machine-safe-stop-plate", [
 ("The uncontrolled extraction machine has a moving feed and an unsecured lifting arm. Stop the feed at the marked intake point, then physically secure the arm before dealing with the main machine. Pressure can weaken the machine's impact; it cannot fasten an arm which has not been secured. The portable clamp earned after this commission is not needed to complete it: this work stand provides the declared fixed brace interface and local securing equipment.", "失控开采机有活动送料与未固定吊臂。先在标记入口停送料，再实际固定吊臂，随后制止主机。压力可以减弱冲击，无法自动固定没有固定的吊臂。本委托之后获得的便携固定钳不是完成前置；站位提供已声明的固定接口和本地固定设备。"),
 ("A successful threat result establishes a stop condition for this particular machine. Check its present supply and the tower load afterwards. It does not choose the town's allocation, appoint duty people or execute a network policy. Those decisions and the current configuration test remain separate work.", "成功处置为这台机器建立停机条件。随后检查当前供电与塔负荷。它没有替矿镇选择分配、任命值守或执行网络政策；这些决定及当前配置测试仍是独立工作。"),
 ("An attempt can be withdrawn to the safe stand and prepared again. Keep the installed brace, the actual feed state and unrelated rescue progress. Returning for a new attempt does not recreate consumed supplies or issue an extra task reward.", "可以撤回安全站位，重新整备尝试。保留已装固定件、真实送料状态与无关救援进展。重试不重新生成已耗物资，也不额外发任务奖励。")])

material("R3-Q304-R-LOAD", "塔站当前配置与交班", "Q-304", "mission_document", "R3-S09.tower_control", "r3-current-deepwell-load-configuration", [
 ("The current bounded arrangement retains seven basic-service units within a local capacity of ten. With early_reduce, extraction is zero. With time_limited_transition, extraction is one to three only during the one declared shift, and two distinct local people must actually hold the operating and safety-watch posts. Check the applied setting, not just the policy saved at the dispatch desk.", "当前有界安排在容量十内保留七单位基本服务。early_reduce抽取零；time_limited_transition仅在一班明确窗口内允许抽取一至三，并由两名不同本地人员实际承担操作与安全观察。检查已应用设置，而非只查调度台保存的政策。"),
 ("At the end of that shift, close_transition_shift at the dispatch duty stand records a real handover and returns extraction to zero before the next shift. Reading, translating, composing or using the dictionary does not advance that work boundary. Every change in feed, securing state or load creates a new configuration that needs its own relevant test.", "该班结束时，在调度值守站位执行close_transition_shift，记录真实交班，在下一班前把抽取降回零。阅读、翻译、写作或查词典不推进这项工作边界。送料、固定状态或负荷变化均形成新配置，需要对应测试。"),
 ("Inspect the tower return route, present isolation and current duty before issuing the local safety handover. A past test remains readable, but a different configuration cannot use its pass. Local safety here is one limited result. Baseline conversion, enhanced controls and later common operating agreements require their own equipment, posts and work receipts.", "地方安全交接前，检查塔站返程、当前隔离与当班岗位。旧测试可以回看，但另一配置不能沿用其通过。本地安全只是有限结果；基础改造、增强控制和后来共同运行协议，各需自己的设备、岗位与工作回执。")], ["Current local load and phase boundary, not six-tower completed engineering flags"])

material("R3-Q304-R-DUTY", "值守登记：两个人，两项职责", "Q-304", "short_notice", "R3-S09.duty", "r3-deepwell-current-duty-board", [
 ("The operating post applies the agreed local load. The safety-watch post records checks and can request a safe stop. They must be held by two different local people who have accepted this assignment. A name on a draft is a proposal. Inspect the actual duty entries and their declared shift before relying on the arrangement.", "操作岗应用约定地方负荷，安全观察岗记录检查并可要求安全停机。须由两名不同本地人员实际承接委托。草稿上的姓名只是提案，应核对真实岗位条目与明确班次。"),
 ("Oren may give a statement, undertake supervised repair or join a travelling crew after the batch finding. Those choices do not appoint him to two simultaneous posts. A local replacement must be accepted before a duty occupant departs. The later ROLE-R3-OP and ROLE-R3-REP protocol mandates also have separate operating and representative scopes; this current shift does not sign them automatically.", "批次核查后，奥伦可作证、承担监督维修或加入出行队伍。这些选择不能同时占两岗。值守人员离开前须有获准接替。后来ROLE-R3-OP与ROLE-R3-REP协议又有独立操作和代表范围，本班不会自动签署那些委托。")])

material("R3-Q304-R-HANDOVER", "送往学城的资料与样本清单", "Q-304", "mission_document", "R3-S01.sample_handover", "r3-academic-verification-dispatch-note", [
 ("The proposed technical package contains the MC-2 instrument reference, retained-copy chain and formal acceptance version, with the current environment readings and their settings. Label the sample with the same observation stage and a lawful receiving purpose: academic verification of the recorded load, extraction and disturbance relationship. Include the known limits and any changed configuration.", "拟送技术包包括MC-2仪表索引、留存抄录链、正式验收版本，以及当前环境读数与设置。样本注明同一观察阶段，并列合法接收用途：学城核验所记录负荷、抽取和扰动关系。保留已知限制及变更配置。"),
 ("At the freight desk, pack the actual sample and authorised fields, name the academic receiving desk and obtain an outgoing handover receipt. A prepared draft does not create a sample or deliver it. Do not attach unrelated household details or copy a private repair conversation without its scope. Keep the original references so that the next reviewer can request the protected sources.", "到货运台实际包装样本及获准字段，列学城接收台并取得发出交接回执。准备好草稿不会生成样本或完成交付。不要附无关住户细节，也不要无范围复制私人维修谈话。保留原索引，让下一复核人可申请受保护来源。"),
 ("An outgoing receipt establishes custody of the stated package at this work boundary. It does not mean that the Glimmer has sailed, that the academic team has completed a test, or that the disturbance has been explained. Record the lawful next inquiry direction without claiming those later results. This package gives no current location or present condition for Mara.", "发出回执说明此工作边界的具名资料保管，不表示微光号已航行、学城已完成试验或扰动已解释。记录合法下一方向，不宣称后来结果。这份资料没有玛拉当前所在或目前状态。")], ["Academic destination is a next-direction/custody candidate, not arrival or validated technical cause"])

material("R3-Q304-R-TOWER", "后续深井塔工程需求", "Q-304", "short_notice", "R3-S09.future_work", "r3-deepwell-future-work-checklist", [
 ("The later baseline work order for TWR-R3 requires one base isolator, one local backup source and two base provisions. Enhanced work calls for one controller, two couplers, three transition crates and one trial fixture, with two operator posts and the actual installation crew arrangement. These are engineering-ledger requirements, not items supplied by reading this checklist.", "TWR-R3后续基础工单要求一隔离器、一地方备用源、二份基础供给。增强工作要求一控制器、二耦合器、三过渡箱、一试运行工装，并落实两操作岗及真实安装队安排。这些属于工程账需求，阅读清单不会交付物品。"),
 ("The local Q-304 result records current safety and a bounded operating handover. It does not fill every baseline, trial, protocol or enhanced requirement. The auxiliary alarm parts, six local work packages, personal equipment and vessel batteries remain separate sources with separate owners.", "本地Q-304结果记录当前安全与有界运行交接，没有填完全部基础、试运行、协议或增强条件。辅助警报器零件、六个地方工包、个人装备和船电池，仍是各有归属的不同来源。")], source_refs=["part07.json:$.engineering.towers[2]", "Character_Progression_v0.1.md:engineering requirements", "NPC_Faction_Reference_v0.1.json:regional_mandates.R3"])

material("R3-Q304-L-TRANSFER", "货运员的样本交接脚本", "Q-304", "listening_script", "R3-S09.handover", "r3-freight-transfer-instruction", [
 ("Freight clerk: Bring the sample to the actual packing stand, with the observation stage and the three document versions. I can acknowledge the authorised outgoing package and keep its custody reference. I cannot acknowledge a sample which has only been named in a draft. The academic receiving desk will still need to inspect what reaches it, and the voyage requires its own vessel and route checks.", "货运员：请带样本到真实包装站位，附观察阶段与三份文书版本。我能确认获准发出包，保留保管索引，不能确认仅写在稿中的样本。学城接收台仍要查实际收到什么，航行也另需船只与航路检查。"),
 ("If the local load has changed since the record was made, keep both the old observation settings and the current configuration. Do not alter the earlier numbers to make the package look consistent. Say which relationship is being tested and which questions remain. The present data can direct a technical inquiry without pretending that it has already found the whole cause.", "记录完成后地方负荷若变动，请同时保留旧观察设置与当前配置。不要为资料看起来一致而修改旧数值。说明待试验的关系与余下问题；当前数据可以引导技术调查，无需假装已经查明全部原因。"),
 ("For the tower handover, confirm the safe return, duty occupants, applied bounded load and current test. If a condition has changed, return to its check before sending. Once the proper work is received, replaying this instruction does not send another sample, appoint another operator or pay the same commission again.", "塔站交接须确认安全返程、值守人员、已应用受限负荷及当前测试。条件变更时，请回到相应检查再交。正确工作接收后，重复这段指示不会再寄一份样本、再任命一名操作员或再次支付同项委托。")])

material("R3-Q304-R-REQUEST", "沃斯的正式技术核验要求", "Q-304", "short_notice", "R3-S09.handover", "r3-voss-formal-academic-verification-request", [
 ("Formal request through the Beacon Office, authorised by Voss: send the local instrument versions, extraction settings and associated disturbance observations to the academic receiving desk for verification. Retain the current safety conditions while the relationship is examined. The receiving inquiry should distinguish an observed association from a tested explanation, and preserve relevant counterexamples or alternative conditions.", "灯署正式渠道要求，由沃斯授权：将地方仪表版本、抽取设置及对应扰动观察送到学城接收台核验。关系核查期间保留当前安全条件。接收调查应区分所见关联与经过试验的解释，并保留相关反例或其他条件。"),
 ("This request specifies a technical purpose and an official receiving route. It does not replace the local batch finding, erase a verified signature or give authority to rewrite the source numbers. The record desk must retain the actual fields and custody versions. A formal request may shape how an inquiry proceeds; its existence is not evidence that every question has been settled.", "要求列明技术用途与正式接收路线，不替代地方批次结论，不抹去已核验签章，也不授权重写来源数值。记录台应保留实际字段与保管版本。正式要求可以影响调查推进方式，其存在尚未证明所有问题已经解决。")], ["Original wording of locked Story6.4 Voss formal verification request; no future motive conclusion or current Mara knowledge"], source_refs=["World_Story_Bible_v0.1.md:489-496", "NPC_Faction_System_v0.1.md:knowledge boundaries"])

material("R3-CQOREN01-R-AUX", "辅助警报器：另一个有范围的工作", "CQ-OREN-01", "mission_document", "R3-S03.alarm_check", "r3-residential-auxiliary-alarm-check", [
 ("Private work invitation, auxiliary alarm A2. The alarm serves two workshop residential rooms. After the main batch finding, Oren may invite help to inspect its damaged connection and define a repair commitment. Accept, decline or pause the invitation; it may later be withdrawn. Accepting an invitation is distinct from permission to publish a conversation or from a decision to recruit him.", "私人工作邀请：辅助警报器A2，服务工坊住区两房。主线批次核查后，奥伦可邀请协助检查损坏接线，并界定维修承诺。可接受、拒绝或暂缓，后来也可撤回；接受邀请与发布谈话许可、招募决定各不相同。"),
 ("At the actual device, inspect the defect, the local workshop repair pack and the agreed scope. Record whether Oren undertakes the work directly or with local help, who will review it and what is still pending. A work list completes this first commitment only when it follows the real inspection. It does not claim that the alarm is repaired or repeat the main mine rescue.", "到真实装置检查缺陷、地方工坊维修包和约定范围。注明奥伦独立承接还是与本地人共同补修、谁复核、哪些仍待做。工作清单须承接真实检查才能形成本节点承诺，尚未宣称警报器修好，也不重复矿井救援。")], ["A2 two-room auxiliary device, separate from main pump/bypass and protected by withdrawable invitation"], access="individual_permission")

material("R3-CQOREN02-R-PARTS", "工坊辅助维修包与独立复核", "CQ-OREN-02", "mission_document", "R3-S03.alarm_repair", "r3-auxiliary-alarm-workshop-pack", [
 ("After Q-304 and the agreed A2 commitment, the workshop can release repair pack AUX-R3-A2 for the invited job. Its connection part is held for this auxiliary device and is separate from personal upgrade parts, the six local extra packages and the tower engineering cargo. The part must actually move from its pack to the device. A saved promise cannot install it.", "Q-304及A2约定承诺之后，工坊可为获邀工作释放AUX-R3-A2维修包。接线件归此辅助设备专用，与个人改件零件、六地方工包和塔工程货分开。零件须实际从包转到装置；保存承诺不能安装。"),
 ("Test the repaired signal in both rooms, then ask another qualified person to repeat the check. Pera may perform or designate that independent review; Oren cannot review his own repair as the second person. Record the actual reviewer and result under the current device version. If the check finds a fault, retain the work done and reopen the remaining defect. Residents may accept the useful repair and still dispute the earlier acceptance.", "在两房测试修复信号，再请另一名合格人员重复检查。佩拉可亲自或指定独立复核；奥伦不能作为第二人复核自己的维修。记录实际复核人与当前装置版本下的结果。检查发现故障时，保留已做工作，继续处理余下缺陷。住民可以接受有用维修，仍质疑早验收。"),
 ("The repaired old tool frame is a personal-line keepsake, with no combat-stat bonus. Keep the historical signature and remaining questions visible. If the private work invitation is withdrawn before confirmation, pause the private work and its outgoing discussion; the already completed main commission and public evidence remain.", "修好的旧工具框是个人线纪念物，没有战斗属性。保留历史签章和余下问题。私人邀请若在确认前撤回，暂停私人工作及对外谈话；已完成主线与公共证据继续保留。")], ["AUX-R3-A2 workshop-supplied repair part, two rooms and versioned independent review; decorative tool frame"], access="individual_permission")

repair = material("R3-CQOREN02-L-REPAIR", "修复不是免除责任：原件对话脚本", "CQ-OREN-02", "listening_script", "R3-S03.alarm_review", "npc-mat-03-oren-repair-original", [
 ("Oren: The signal now reaches both rooms. I replaced the damaged connection, and the spare parts are listed here. Someone other than me should test it before the residents rely on it.", "奥伦：信号现在能到两间房。我替换了损坏接线，备用零件列在这里。住民依赖它之前，应该由我之外的人测试。"),
 ("Pera: That is a useful repair. It does not answer why the earlier equipment was accepted with the safety check incomplete.", "佩拉：这项维修有用，但它尚未回答，为什么早先设备在安全检查未完成时就按合格验收。"),
 ("Oren: I am not asking it to. I signed that record, and I should have refused. I can explain the pressure I was under, but that does not make the signature belong to someone else.", "奥伦：我没有要求它回答。我签了那份记录，本该拒绝。我可以说明当时受到的压力，但签名仍然属于我。"),
 ("Player: What can be agreed today without closing the wider review?", "玩家：广泛复核仍未结束，今天可以商定什么？"),
 ("Pera: We can appoint a reviewer for this repair and make the result available to the residents. His statement about the earlier check must remain separate. I will not write that everyone has forgiven him.", "佩拉：我们可为此维修指定复核人，让住民看到结果。他关于早检查的陈述另行保留。我不会写所有人已经原谅他。"),
 ("Oren: Then record the repair and the remaining questions separately. I can also train someone to repeat the test. I will not always be here to do it.", "奥伦：那就分记维修和余下问题。我也能教另一人重复测试；我不会一直在这里执行。")], ["Reference English preserved with speaker prefixes; new Chinese translation candidate; only after real auxiliary repair, independent review still pending"], access="individual_permission", source_refs=["reference/part09/materials/NPC-MAT-03_Oren_Repair.md", "NPC_Faction_System_v0.1.md:333-347"])
repair["originality"] = "reference_dialogue_preserved_translation_candidate"

material("R3-O01-R-MUSIC", "修理铺：音乐盒的齿轮与回忆", "R3-O01", "mission_document", "R3-O01.parts", "r3-owner-musicbox-repair-note", [
 ("The owner invites a repair of the music box and permits inspection of its mechanism. A note supplied with this box specifies a twelve-tooth replacement wheel, MBOX-12. The store also holds a fourteen-tooth wheel for another device. Read the specification before asking the owner to approve the chosen part. The small box belongs to the owner; it is not a reward item or a main-line key.", "主人邀请修音乐盒，允许检查机构。随盒说明要求十二齿替换轮MBOX-12，铺内另有给别装置用的十四齿轮。请求主人批准选件前，请核对规格。盒子属于主人，不是奖励物品或主线钥匙。"),
 ("The owner remembers hearing it at a family meal and may choose to describe that memory privately. Their permission to repair the mechanism does not publish the memory. Ask separately before copying a personal account into a notice. The repair can be paused if permission changes, and the owner may keep the original note without telling the story.", "主人记得家庭聚餐时听过它，可以选择私下讲回忆。维修机构许可不会公开回忆。把个人叙述抄进告示前需另问。许可改变时可以暂停维修，主人也能保留原便条、不讲故事。"),
 ("After fitting an approved part, inspect the turning mechanism and return the same box. A written repair note can state the part used, check performed and limits of the work. The owner can keep that note with the original specification and leave the family memory private. A useful repair does not require a public story.", "安装获准件后，检查旋转机构并归还同一个盒子。书面记录可列所用零件、检查和工作限制。主人可将记录与原规格一同保存，保留家庭回忆私密；有用维修无需一个公开故事。")], ["Original MBOX12 twelve-tooth vs fourteen-tooth local optional repair; owner consent separate from publication; no rewards registered"], access="individual_permission")

material("R3-O02-R-OBSERVE", "侧井观察：一条记录的条件", "R3-O02", "mission_document", "R3-O02.record", "r3-sidewell-optional-observation", [
 ("This safe observation point is optional. Its sheet records a sheltered side-well stage with extraction at one local unit and disturbance reading five. The main cutting-face sheet records a reading of four at a one-unit stage elsewhere. The two observations differ in place and sampling conditions. Keep those differences rather than treating the matching extraction settings as a controlled experiment.", "此安全观察点为可选。页面记录避护侧井一阶段：抽取一地方单位、扰动五。主采掘面另一处一单位阶段读数为四。两次观察地点与取样条件不同，应保留差异，不能把相同抽取设置当受控试验。"),
 ("A comparison note may propose what another observer should record next, such as the instrument, pump state and stage. Do not write that this extra sheet proves the final cause of the mist or unlocks a hidden ending condition. The necessary chapter samples and instrument evidence remain on the main route whether this point is visited or not.", "比较便条可以提出下一观察要记录什么，例如仪表、泵状态与阶段。不能写这页证明雾的最终原因或开启隐藏结局条件。无论访问此点与否，必需章节样本和仪表证据均在主路。"),
 ("Keep to the marked observation stand unless a separate safe sampling assignment is given. A note can be useful even when no additional sample is taken. Retain the sheet's place, stage and instrument reference so that a later reviewer can compare conditions. If a condition is unknown, leave it unknown rather than copying the main site's setting into this record.", "另有安全取样委托前，请留在标记观察站位。没有追加样本，便条仍可有用。保留此页地点、阶段与仪表索引，让后来复核者能比较条件。条件未知时保留未知，不把主采点设置抄来填入此记录。")], ["Original optional reading5 at extraction1; contextual comparison not controlled-cause proof; no unique main evidence"])

for mid, docversion in [("R3-Q302-R-RAW", "MC-2.instrument.I@1"), ("R3-Q302-R-COPY", "MC-2.retained.I@1"), ("R3-Q302-R-SIGNED", "MC-2.acceptance@3")]:
    item = next(m for m in MATERIALS if m["id"] == mid)
    item["document_identity"] = docversion
    item["paragraphs"][0]["en"] = "Document identity: " + docversion + ". " + item["paragraphs"][0]["en"]
    item["paragraphs"][0]["zh"] = "文书身份：" + docversion + "。" + item["paragraphs"][0]["zh"]

commission = next(m for m in MATERIALS if m["id"]=="R3-Q301-R-COMMISSION")
commission["paragraphs"].append(dict(id="R3-Q301-R-COMMISSION-p05",
    en="For the controlled batch records, apply at the workshop comparison stand to the local record desk, R3-local-record-desk. The available fields are check_status, acceptance_status, signatory_scope and version_source. The recipient is patrol_technician; the purpose is verify_original_instruments_and_acceptance; the requested source set is MC2-current-source-set. The desk must issue this actual scoped permission before the protected pages are opened. A mine work assignment does not grant unrelated names or a private interview.",
    zh="受控批次记录须到工坊比较站位向地方记录台R3-local-record-desk申请。可用字段为check_status、acceptance_status、signatory_scope、version_source；接收方patrol_technician，用途verify_original_instruments_and_acceptance，请求来源集合MC2-current-source-set。保护页开启前，记录台须实际签发这项有限许可；矿井委托不会开放无关姓名或私人访谈。"))

