def emit(name, value):
    temporary = HERE / (name+".pending")
    temporary.write_text(json.dumps(value,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    temporary.replace(HERE/name)

def assemble():
    # Mechanical authoring checks only: they prove no playthrough, audio, human approval or semantic calibration.
    mids=[m["id"] for m in MATERIALS]
    spots={p["id"] for scene in SCENES for p in scene["spots"]}
    assert len(mids)==len(set(mids))
    assert len(STATIONS)==len({s["id"] for s in STATIONS})
    assert len(WRITING)==len({w["id"] for w in WRITING})
    assert len(spots)==sum(len(s["spots"]) for s in SCENES)
    assert len({p["id"] for m in MATERIALS for p in m["paragraphs"]})==sum(len(m["paragraphs"]) for m in MATERIALS)
    assert len(SCENES)==11 and sum(len(s["ports"]) for s in SCENES)==22
    assert len([m for m in MATERIALS if m["kind"]=="extended_reading"])==2
    for m in MATERIALS:
        assert m["location"]["spot"] in spots and all(p["en"] and p["zh"] for p in m["paragraphs"])
        if m["kind"]=="extended_reading": assert 600<=m["english_word_count"]<=950,(m["id"],m["english_word_count"])
        if m.get("planned_audio_class")=="long_audio": assert m["english_word_count"]>=700,(m["id"],m["english_word_count"])
    for station in STATIONS: assert station["spot"] in spots
    for w in WRITING: assert w["workspace_spot"] in spots and all(mid in mids for mid in w["sources"])
    for scene in SCENES:
        for port in scene["ports"]:
            assert any(p["id"]==port["target_port"] and p["target_port"]==port["id"] for p in SCENE_BY_ID[port["target_scene"]]["ports"])
    emit("learner_package.json",PACKAGE)
    paths=["AGENTS.md","docs/integration/MASTER_GDD_v0.1.md","docs/integration/Integration_Decisions_v0.1.md","reports/continuous/Scope_20261009.md"]
    paths += [f"planning/tasks/CP-R3-{i:02d}.md" for i in range(1,7)]
    paths += ["docs/baseline/"+name+"_v0.1.md" for name in ["World_Story_Bible","Exploration_Level_Design","Quest_Event_System","English_Learning_System","Puzzle_System","Character_Progression","Combat_System","NPC_Faction_System","UI_UX_Spec","Content_AI_Pipeline"]]
    paths += ["reference/part04/data/Quest_Event_Reference_v0.1.json","reference/part05/data/English_Learning_Reference_v0.1.json","reference/part05/data/Original_Materials_v0.1.json","reference/part06/data/Puzzle_Reference_v0.1.json","reference/part08/data/Combat_Reference_v0.1.json","reference/part09/data/NPC_Faction_Reference_v0.1.json","reference/part09/materials/NPC-MAT-03_Oren_Repair.md","content/source/chapter_two/learner_package.json"]
    provenance=dict(content_version=VERSION,scope="author_only_source_provenance",player_projection=False,review_status="original_unreviewed",human_review="human_pending",candidate_status="frozen_author_candidate_not_runtime",
        source_files=[dict(path=p,sha256=hashlib.sha256((ROOT/p).read_bytes()).hexdigest()) for p in paths],
        artifacts=[dict(path="content/source/chapter_three/"+p,sha256=hashlib.sha256((HERE/p).read_bytes()).hexdigest()) for p in ["learner_package.json","build.author_only.py","production_cards.author_only.md","INTEGRATION.author_only.md"] if (HERE/p).exists()],
        mechanical_authoring_checks=dict(unique_ids=True,paired_ports=22,materials_have_complete_bilingual_paragraphs=True,writing_references_resolve=True,station_locations_resolve=True,
            scope="executed local static authoring assembly assertions only; not runtime/world/UI tests"),
        counts=dict(main_scenes=9,optional_scenes=2,paired_ports=22,materials=len(MATERIALS),extended_readings=2,main_listening_scripts=5,main_long_listening_scripts=2,
            personal_line_reference_script=1,recorded_audio_assets=0,full_visual_writing=1,full_argument_writing=1,all_writing_tasks=len(WRITING),stations=len(STATIONS),original_lexical_candidates=len(LEXICAL),
            material_english_words=sum(m["english_word_count"] for m in MATERIALS)),
        per_material_word_counts={m["id"]:m["english_word_count"] for m in MATERIALS},
        original_local_details=[dict(material=m["id"],details=m["original_local_details"]) for m in MATERIALS if m["original_local_details"]],
        not_run=["runtime_continuous_chapter_playthrough","native_geometry_collision_and_pathing","lowest_roster_all_encounters_balance","real_recording_and_full_audition","human_story_English_Chinese_review","Academic_6.5_target_group_calibration","independent_full_Task1_Task2_assessment","voice_and_performance_rights","optional_contract_registration","later_tower_engineering_completion"],
        human_signoff=None,release_gate_accepted=False)
    emit("provenance.author_only.json",provenance)
    print(json.dumps(dict(scope="static authoring assembly only",content_version=VERSION,counts=provenance["counts"],long_material_words={m["id"]:m["english_word_count"] for m in MATERIALS if m["kind"]=="extended_reading" or m.get("planned_audio_class")=="long_audio"},human_review="human_pending",audio_assets=0),ensure_ascii=False))

